export type FakeRequest = {
  method: string;
  path: string;
  body: unknown;
};

export type FakeResponse = {
  status?: number;
  json?: unknown;
  text?: string;
};

export type FakeRoute = {
  method?: string;
  path: string | RegExp;
  respond: FakeResponse | ((request: FakeRequest) => FakeResponse);
};

const parseBody = (body: BodyInit | null | undefined): unknown => {
  if (typeof body !== "string") return body ?? undefined;
  try {
    return JSON.parse(body);
  } catch {
    return body;
  }
};

const pathOf = (input: RequestInfo | URL): string => {
  const raw = typeof input === "string" ? input : input instanceof URL ? input.href : input.url;
  const url = new URL(raw, "http://localhost");
  return `${url.pathname}${url.search}`;
};

const matches = (route: FakeRoute, request: FakeRequest): boolean => {
  const methodMatches = (route.method ?? "GET").toUpperCase() === request.method;
  const pathMatches =
    typeof route.path === "string" ? route.path === request.path : route.path.test(request.path);
  return methodMatches && pathMatches;
};

const toResponse = ({ status = 200, json, text }: FakeResponse): Response => {
  if (json !== undefined) {
    return new Response(JSON.stringify(json), {
      status,
      headers: { "content-type": "application/json" },
    });
  }
  return new Response(text ?? "", { status });
};

export const createFakeApi = (routes: readonly FakeRoute[]) => {
  const requests: FakeRequest[] = [];

  const fakeFetch = async (input: RequestInfo | URL, init?: RequestInit): Promise<Response> => {
    const request: FakeRequest = {
      method: (init?.method ?? "GET").toUpperCase(),
      path: pathOf(input),
      body: parseBody(init?.body),
    };
    requests.push(request);
    const route = routes.find((candidate) => matches(candidate, request));
    if (!route) {
      return toResponse({ status: 404, text: `No fake route for ${request.method} ${request.path}` });
    }
    return toResponse(typeof route.respond === "function" ? route.respond(request) : route.respond);
  };

  return { fetch: fakeFetch, requests };
};
EOF
cat > apps/user-ui/src/characterisation/fake-websocket.ts <<'EOF'
type SocketHandler<E> = ((event: E) => void) | null;

export type FakeWebSocketInstance = {
  readonly url: string;
  readonly sent: string[];
  readyState: number;
  onopen: SocketHandler<Event>;
  onmessage: SocketHandler<{ data: string }>;
  onclose: SocketHandler<Event>;
  onerror: SocketHandler<Event>;
  send: (data: string) => void;
  close: () => void;
  open: () => void;
  receive: (message: unknown) => void;
  dropConnection: () => void;
};

export const createFakeWebSocket = () => {
  const sockets: FakeWebSocketInstance[] = [];

  class FakeWebSocket implements FakeWebSocketInstance {
    static readonly CONNECTING = 0;
    static readonly OPEN = 1;
    static readonly CLOSING = 2;
    static readonly CLOSED = 3;

    readonly sent: string[] = [];
    readyState = FakeWebSocket.CONNECTING;
    onopen: SocketHandler<Event> = null;
    onmessage: SocketHandler<{ data: string }> = null;
    onclose: SocketHandler<Event> = null;
    onerror: SocketHandler<Event> = null;

    constructor(readonly url: string) {
      sockets.push(this);
    }

    send(data: string) {
      this.sent.push(data);
    }

    close() {
      this.dropConnection();
    }

    open() {
      this.readyState = FakeWebSocket.OPEN;
      this.onopen?.(new Event("open"));
    }

    receive(message: unknown) {
      this.onmessage?.({ data: JSON.stringify(message) });
    }

    dropConnection() {
      if (this.readyState === FakeWebSocket.CLOSED) return;
      this.readyState = FakeWebSocket.CLOSED;
      this.onclose?.(new Event("close"));
    }
  }

  return { WebSocketClass: FakeWebSocket, sockets };
};
